def _materialize_agent():
    source_code = zlib.decompress(base64.b85decode(PAYLOAD.encode('ascii'))).decode('utf-8')
    scope = {}
    exec(source_code, scope)
    return scope['agent']

_agent_fn = _materialize_agent()

def agent(obs, *args, **kwargs):
    return _agent_fn(obs)
